"""Build fully self-contained offline HTML for the spatial mechanotransduction sweep."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import pandas as pd

def html(out):
    out=Path(out)
    d=pd.read_csv(out/'visco_metrics.csv');c=pd.read_csv(out/'time_curves.csv');a=pd.read_csv(out/'adhesion_site_map.csv')
    # Round numeric arrays for display; preserve enough precision for scientific data in CSV.
    def obj(df):return json.loads(df.to_json(orient='records',double_precision=7))
    vals={"metrics":obj(d),"curves":obj(c),"sites":obj(a)}
    data=json.dumps(vals,separators=(',',':')).replace('</','<\\/')
    template=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Collagen Mechanics Explorer | Viscoelastic adhesion lab</title>
<style>
:root{--base:#0c111c;--surface:#162030;--surface2:#1d2b3c;--text:#e3edfa;--muted:#96abc1;--accent:#85d5c2;--hot:#f3a467;--line:#35475d;--blue:#90b6ed}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 75% 3%,#193146,#0c111c 53%);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--text)} main{max-width:1240px;margin:auto;padding:26px 20px 50px}h1{font-size:clamp(26px,4vw,42px);line-height:1.16;margin:8px 0 9px;letter-spacing:-.025em}h2{font-size:17px;margin:4px 0 13px}.eyebrow{color:var(--accent);font-size:12px;letter-spacing:.18em;text-transform:uppercase;font-weight:700}.intro{max-width:820px;color:var(--muted)}.grid{display:grid;gap:14px;grid-template-columns:repeat(12,1fr)}.pane{border:1px solid #344458;border-radius:16px;padding:20px;background:rgba(22,32,48,.92);min-width:0}.controls{grid-column:1/-1}.half{grid-column:span 6}.full{grid-column:1/-1}.third{grid-column:span 4}.inputs{display:flex;gap:12px;flex-wrap:wrap}label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--muted);font-weight:700;min-width:155px;flex:1}select{padding:12px;background:var(--surface2);border:1px solid var(--line);color:var(--text);border-radius:10px;font:inherit;width:100%}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:17px}.stat{background:var(--surface2);padding:15px;border-radius:12px}.stat span{display:block;font-size:11px;color:var(--muted)}.stat strong{display:block;font-size:25px;line-height:1.3;font-variant-numeric:tabular-nums}.stat small{color:var(--muted);font-size:10px}.viz{width:100%;height:310px;display:block}.legend{display:flex;gap:17px;flex-wrap:wrap;color:var(--muted);font-size:12px}.legend i{width:9px;height:9px;display:inline-block;border-radius:50%;margin-right:4px}.note{color:var(--muted);font-size:12px;margin-top:8px}.warning{border-left:3px solid var(--hot);color:#edd8c7;background:#2a2430;padding:12px 15px;border-radius:6px;font-size:13px;margin:15px 0}.kicker{font-size:12px;text-transform:uppercase;color:var(--muted);letter-spacing:.1em}.footer{margin-top:22px;border-top:1px solid var(--line);padding:20px 0;color:var(--muted);font-size:13px}a{color:var(--accent)}@media(max-width:840px){.half,.third{grid-column:1/-1}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:460px){.stats{grid-template-columns:1fr}}
</style></head><body><main><div class="eyebrow">ScienceClaw · Computational hypothesis laboratory</div><h1>Where collagen ages matters.</h1><p class="intro">Explore how collagen density, AGE/LOX crosslinks, fibronectin–TG2 reinforcement, and oxidative damage redistribute forces around a contracting cell. Viscoelasticity, frequency response and a deliberately <em>uncalibrated</em> FAK–YAP mechanosignaling proxy are computed from a passive two-protein spring network.</p>
<div class="warning"><b>Scientific scope:</b> This is not protein-level MD, a measured fibroblast signaling response, a prediction of clinical lung function, or calibrated collagen density in mg/mL. Density, time, forces, modulus and YAP are normalized. Biochemistry names label hypothetical coarse-grained interventions.</div>
<div class="grid"><section class="pane controls"><div class="kicker">Select a physical experiment</div><div class="inputs">
<label>Collagen density <select id="density"></select></label><label>Crosslink / damage <select id="chemistry"></select></label><label>Where located <select id="zone"></select></label><label>Collagen distribution <select id="profile"></select></label><label>Random network <select id="seed"></select></label></div>
<div class="stats"><div class="stat"><span>Storage stiffness E′ (ω=1)</span><strong id="storage">–</strong><small>Higher = greater elastic resistance</small></div><div class="stat"><span>Loss tangent E″/E′</span><strong id="loss">–</strong><small>Higher = more dissipative at this frequency</small></div><div class="stat"><span>Traction retained after t=12</span><strong id="persist">–</strong><small>Cell pull relaxes over time</small></div><div class="stat"><span>YAP/TAZ proxy</span><strong id="yap">–</strong><small>Not a measured probability</small></div></div></section>
<section class="pane half"><h2>1 · Stress relaxation at cell contacts</h2><canvas id="relax" class="viz" aria-label="Traction and YAP trajectories"></canvas><div class="legend"><span><i style="background:var(--accent)"></i>F(t)/F(0)</span><span><i style="background:var(--hot)"></i>YAP spatial proxy</span></div><p class="note">A fixed cell contraction is applied. Maxwell-like internal variables cause local force redistribution and mechanical relaxation.</p></section>
<section class="pane half"><h2>2 · The cell's 12 adhesion sites</h2><canvas id="map" class="viz" aria-label="Traction points around the cell"></canvas><div class="legend"><span><i style="background:var(--accent)"></i>Collagen I adhesions</span><span><i style="background:var(--hot)"></i>Fibronectin adhesions</span></div><p class="note">Circle area scales with late force at each modeled adhesion. Front faces right. The illustrated geometry is planar, not a cell reconstruction.</p></section>
<section class="pane half"><h2>3 · Crosslink location versus mechanosignaling</h2><canvas id="locations" class="viz"></canvas><p class="note">Bars compare spatial YAP proxies across different regions for the same density, chemistry and seed. Bulk stiffness can remain similar while local mechanosensing changes.</p></section>
<section class="pane half"><h2>4 · What a bulk-only model would miss</h2><div id="detail"></div><p class="note">Spatial, site-averaged, and traction-permuted controls all use the same illustrative signaling equations. Site polarity and receptor weighting are hypotheses, not fitted biology.</p></section>
<section class="pane full"><h2>Assumptions and scientific next steps</h2><p>Collagen I and fibronectin are separate elastic/viscoelastic fiber graphs, coupled through effective protein interactions. LOX- and AGE-like modifications are permanent-biased springs, fibronectin–TG2 adds effective links, oxidative damage weakens collagen fibers, and the 4-HNE arm weakens a subset of fibronectin fibers and some integrin-site parameters. Reactive chemistry is <em>not</em> simulated. Test predictions against AFM microrheology near cells, experimental traction-force microscopy, dynamic rheometry, and matched-stiffness FAK/YAP microscopy before making biological claims.</p><p><a href="https://humanavianaisymbiosis.wordpress.com/collagen-jamming-aging-crosslinks-mechanotransduction-scienceclaw/" target="_blank" rel="noopener">Jamming-and-aging research note</a> · <a href="https://pubmed.ncbi.nlm.nih.gov/27140623/" target="_blank" rel="noopener">Weak-bond stress relaxation in collagen</a> · <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5526213/" target="_blank" rel="noopener">Pericellular heterogeneity</a> · <a href="https://pubmed.ncbi.nlm.nih.gov/38135164/" target="_blank" rel="noopener">TG2/fibronectin mechano-regulation</a>.</p></section></div><div class="footer">Built from 921 independently executed, converged numerical configurations across three random network seeds. All details and higher precision values are preserved in the accompanying CSV data. No external JavaScript libraries or network connection are required to explore this page.</div></main>
<script>const DATA=__EMBEDDED_DATA__;
const q=id=>document.getElementById(id), names={reference:'Young reference',LOX:'LOX-like collagen link',AGE:'AGE-like collagen link',TG2_FN:'TG2–fibronectin reinforcement',oxidative_cleavage:'Oxidative fiber damage', '4HNE_FN':'4-HNE fibronectin proxy',AGE_TG2:'Mixed AGE and TG2'};
const nums=arr=>[...new Set(arr)].sort((a,b)=>typeof a==='number'?a-b:String(a).localeCompare(String(b)));
const selectors={density:'collagen_density',chemistry:'chemistry',zone:'location',profile:'density_profile',seed:'seed'};
function available(key){const criteria={};for(const [id,field] of Object.entries(selectors))if(id!==key)criteria[field]=read(id);return DATA.metrics.filter(v=>Object.entries(criteria).every(([k,val])=>val===null||v[k]===val)).map(x=>x[selectors[key]]);}
function read(id){const x=q(id);if(!x.value)return null;return id==='density'||id==='seed'?Number(x.value):x.value}
function setOptions(id,available,preferred){const opts=nums(available),v=opts.includes(preferred)?preferred:opts[0];q(id).innerHTML=opts.map(x=>`<option value="${x}">${id==='chemistry'?(names[x]||x):x}</option>`).join('');if(v!==undefined)q(id).value=v}
function init(){const d=DATA.metrics;setOptions('density',d.map(x=>x.collagen_density),1);setOptions('chemistry',d.map(x=>x.chemistry),'AGE');setOptions('zone',d.map(x=>x.location),'front');setOptions('profile',d.map(x=>x.density_profile),'uniform');setOptions('seed',d.map(x=>x.seed),1);update()}
function findRow(){const select=Object.fromEntries(Object.entries(selectors).map(([k,v])=>[v,read(k)]));return DATA.metrics.find(x=>Object.entries(select).every(([k,v])=>x[k]===v))}
function update(changed){let row=findRow();if(!row){let compatible=DATA.metrics.filter(r=>r.collagen_density===read('density')&&r.chemistry===read('chemistry')&&r.seed===read('seed')&&r.density_profile===read('profile'));
 if(!compatible.length)compatible=DATA.metrics.filter(r=>r.collagen_density===read('density')&&r.chemistry===read('chemistry')&&r.seed===read('seed'));
 if(!compatible.length)compatible=DATA.metrics;row=compatible[0];for(const [key,col] of Object.entries(selectors))q(key).value=row[col];}
 const keyCols=['seed','collagen_density','density_profile','chemistry','location'];const eq=x=>keyCols.every(k=>x[k]===row[k]);
 const curves=DATA.curves.filter(eq).sort((a,b)=>a.time-b.time),sites=DATA.sites.filter(eq).sort((a,b)=>a.adhesion-b.adhesion);
 q('storage').textContent=row.Eprime_mid.toFixed(3);q('loss').textContent=row.tandelta_mid.toFixed(3);q('persist').textContent=(100*row.traction_persistence).toFixed(1)+'%';q('yap').textContent=row.YAP_spatial.toFixed(3);
 drawLines(q('relax'),curves,[["total_cell_traction",'#85d5c2',true],["YAP_spatial",'#f3a467',false]]);
 drawAdhesions(q('map'),sites);drawLocations(q('locations'),row);
 q('detail').innerHTML=`<p class="intro">At this setting, estimated <strong>spatial YAP proxy ${row.YAP_spatial.toFixed(3)}</strong> contrasts with a mean-adhesion-only proxy of <strong>${row.YAP_mean_only.toFixed(3)}</strong>, and a 180° force-permuted proxy of <strong>${row.YAP_permuted.toFixed(3)}</strong>. The latter retains the exact force distribution but changes which adhesion sites carry it.</p><p class="intro">Front adhesions carry average late traction ${row.front_late.toFixed(4)}; rear adhesions ${row.rear_late.toFixed(4)}. The time-dependent total traction changed from ${row.initial_traction.toFixed(4)} to ${row.late_traction.toFixed(4)}. The modeled complex stiffness has loss component ${row.Edoubleprime_mid.toFixed(3)} at ω=1.</p><p class="note">All these values are dimensionless and depend on assumed mechanosignaling thresholds, adhesive polarization, and relaxation rates. Changing the spatial position of crosslinks can change local tractions without giving a unique biological YAP prediction.</p>`;
}
function context(c){const dpr=window.devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*dpr;c.height=h*dpr;const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);return {ctx,w,h}}
function drawLines(canvas,data,keys){let {ctx,w,h}=context(canvas);if(!data.length)return;const pad={l:44,r:20,t:15,b:32},W=w-pad.l-pad.r,H=h-pad.t-pad.b;ctx.strokeStyle='#516779';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad.l,pad.t);ctx.lineTo(pad.l,h-pad.b);ctx.lineTo(w-pad.r,h-pad.b);ctx.stroke();ctx.fillStyle='#9aadc2';ctx.font='11px system-ui';for(let j=0;j<=4;j++){const v=j/4;ctx.fillText(v.toFixed(2),4,pad.t+H*(1-v)+4);ctx.strokeStyle='rgba(115,140,162,.12)';ctx.beginPath();ctx.moveTo(pad.l,pad.t+H*(1-v));ctx.lineTo(w-pad.r,pad.t+H*(1-v));ctx.stroke()}const maxTime=Math.max(...data.map(x=>x.time));ctx.fillText('t = '+maxTime, w-pad.r-45,h-8);for(const [k,color,normalize] of keys){const base=normalize?data[0][k]:1;ctx.strokeStyle=color;ctx.lineWidth=2.4;ctx.beginPath();data.forEach((d,i)=>{const x=pad.l+W*d.time/maxTime,y=pad.t+H*(1-d[k]/base);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke()}}
function drawAdhesions(canvas,sites){const {ctx,w,h}=context(canvas);if(!sites.length)return;const cx=w*.5,cy=h*.48,rx=Math.min(w*.38,h*.42),ry=Math.min(w*.30,h*.34);ctx.strokeStyle='#63758b';ctx.setLineDash([5,4]);ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.font='12px system-ui';ctx.fillStyle='#adbed1';ctx.fillText('REAR',Math.max(5,cx-rx-45),cy-ry-14);ctx.fillText('FRONT →',Math.min(w-80,cx+rx-20),cy-ry-14);const max=Math.max(...sites.map(v=>v.late_traction),.001);for(const s of sites){const ang=s.angle_degrees*Math.PI/180,x=cx+rx*Math.cos(ang),y=cy-ry*Math.sin(ang),rad=5+17*Math.sqrt(s.late_traction/max);ctx.beginPath();ctx.arc(x,y,rad,0,Math.PI*2);ctx.fillStyle=s.protein==='FN'?'rgba(243,164,103,.83)':'rgba(133,213,194,.85)';ctx.fill();ctx.strokeStyle='#152b37';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#0c111c';ctx.textAlign='center';ctx.font='10px system-ui';ctx.fillText(String(s.adhesion+1),x,y+3)}ctx.textAlign='start'}
function drawLocations(canvas,row){const {ctx,w,h}=context(canvas);const ss=DATA.metrics.filter(x=>x.chemistry===row.chemistry&&x.seed===row.seed&&x.density_profile===row.density_profile&&x.collagen_density===row.collagen_density);const order=['uniform','front','rear','flanks','pericellular','far'],items=order.map(zone=>ss.find(x=>x.location===zone)).filter(Boolean);if(!items.length)return;const max=Math.max(...items.map(x=>x.YAP_spatial),.1),p=25,dx=(w-2*p)/items.length;items.forEach((d,i)=>{const bx=p+i*dx+dx*.15,bw=dx*.68,barh=(h-80)*d.YAP_spatial/max;ctx.fillStyle=d.location===row.location?'#85d5c2':'#708ca9';ctx.fillRect(bx,h-45-barh,bw,barh);ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillStyle='#d4e1ef';ctx.fillText(d.YAP_spatial.toFixed(2),bx+bw/2,h-50-barh);ctx.fillStyle='#aabbce';const label=d.location==='pericellular'?'near cell':d.location;ctx.fillText(label,bx+bw/2,h-23)});ctx.textAlign='start'}
for(const id of Object.keys(selectors))q(id).addEventListener('change',()=>update(id));window.addEventListener('resize',()=>update());init();
</script></body></html>'''
    target=out/'interactive_explorer.html'
    target.write_text(template.replace('__EMBEDDED_DATA__',data),encoding='utf-8')
    print('Wrote',target,'bytes',target.stat().st_size)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--out',default='results/viscoelastic_study');x=p.parse_args();html(x.out)
